//! The write guard of Rating (generated by metaphor-schema; do not edit). It lives in a
//! file of its own because `rating_service.rs` is hand-owned.

#[allow(unused_imports)]
use super::*;
use crate::domain::entity::Rating;

/// The rules the schema declares for Rating, checked against the row a create or update
/// would store. The generated build attaches it to [`RatingService`]. A refusing rule's
/// break answers 422; a rule in shadow is logged under `backbone::write_guard` and the
/// write goes ahead.
pub struct RatingRowRules;

#[async_trait::async_trait]
impl backbone_core::write_guard::WriteGuard<Rating> for RatingRowRules {
    async fn check(
        &self,
        ctx: &backbone_core::write_guard::WriteCtx<'_, Rating>,
    ) -> backbone_core::write_guard::GuardOutcome {
        use backbone_core::row_rule as r;
        use backbone_core::violation::Violation;
        use backbone_core::write_guard::{GuardOutcome, WriteKind};
        let (create, update) = (ctx.kind == WriteKind::Create, ctx.kind == WriteKind::Update);
        let Some(after) = ctx.after.filter(|_| create || update) else {
            return GuardOutcome::allow();
        };
        let Ok(row) = serde_json::to_value(after) else {
            return GuardOutcome::allow();
        };
        let row = &row;
        let old = ctx.before.and_then(|b| serde_json::to_value(b).ok());
        let shadow = Vec::new();
        let mut refuse = Vec::new();
        // `session_id_required` (@required on Rating.session_id)
        if (create || (update && r::changed(old.as_ref(), row, &["session_id"]))) && !r::holds(&r::and(r::is_not_null(r::field(row, "session_id")), r::not(r::is_empty(r::trim(r::field(row, "session_id")))))) {
            refuse.push(Violation::new("session_id", "required", "session_id is required"));
        }
        // `comment_max_length` (@max(2000) on Rating.comment)
        if (create || (update && r::changed(old.as_ref(), row, &["comment"]))) && !r::holds(&r::le(r::length(r::field(row, "comment")), r::Val::Num(2000.0_f64))) {
            refuse.push(Violation::new("comment", "max_length", "comment must be at most 2000 characters").with_param("max", 2000_i64));
        }
        GuardOutcome { refuse, shadow }
    }
}
